// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type PasswordLoopProps = Record<string, any>;

const PasswordLoop: React.FC<PasswordLoopProps> = ({
  backgroundColor = "#016f9e",
  transparentBackground = false,
  durationInSeconds = 5,
  loginTitle = "Sign in",
  forgotPasswordText = "Forgot password?",
  resetTitle = "Reset password",
  dropoffText = "Drop-off",
  phoneBackgroundColor = "#ffffff",
  textColor = "#1a1a1a",
  accentColor = "#016f9e",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings for transitions (Login -> Reset -> Login -> Reset -> Login -> Exit)
  // Loop 1
  const click1Frame = 30;
  const reset1ReturnFrame = 55;
  // Loop 2
  const click2Frame = 85;
  const reset2ReturnFrame = 105;
  // Drop-off
  const exitFrame = 120;

  // Screen sliding calculations using additive/subtractive springs
  const t1 = spring({ frame: frame - click1Frame, fps, config: { damping: 15 } });
  const t2 = spring({ frame: frame - reset1ReturnFrame, fps, config: { damping: 15 } });
  const t3 = spring({ frame: frame - click2Frame, fps, config: { damping: 15 } });
  const t4 = spring({ frame: frame - reset2ReturnFrame, fps, config: { damping: 15 } });
  
  // 0 = Login Screen, 1 = Reset Screen
  const screenOffset = t1 - t2 + t3 - t4;

  // Interaction feedback (scale down when "tapped")
  const tap1Scale = interpolate(
    frame, 
    [click1Frame - 4, click1Frame, click1Frame + 4], 
    [1, 0.9, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const tap2Scale = interpolate(
    frame, 
    [click2Frame - 4, click2Frame, click2Frame + 4], 
    [1, 0.9, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const activeTapScale = tap1Scale * tap2Scale;

  // Final Drop-off Animation
  const exitSpring = spring({ 
    frame: frame - exitFrame, 
    fps, 
    config: { damping: 14, mass: 1.2, stiffness: 80 } 
  });
  
  const phoneYOffset = exitSpring * (height * 1.5); // Slides down off screen

  // Background Text Appearance
  const textScale = spring({ frame: frame - exitFrame, fps, config: { damping: 12 } });
  const textOpacity = interpolate(
    frame, 
    [exitFrame, exitFrame + 10], 
    [0, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: interFamily, 
      alignItems: "center", 
      justifyContent: "center",
      transition: "none"
    }}>
      
      {/* Background Drop-off Message */}
      <div style={{
        position: "absolute",
        opacity: textOpacity,
        transform: `scale(${textScale})`,
        fontSize: 100,
        fontWeight: 800,
        color: "#ffffff",
        textTransform: "uppercase",
        letterSpacing: "4px",
        textAlign: "center",
        transition: "none"
      }}>
        {dropoffText}
      </div>

      {/* Mobile Device Container */}
      <div style={{
        width: width * 0.85,
        height: height * 0.65,
        backgroundColor: phoneBackgroundColor,
        borderRadius: 48,
        overflow: "hidden",
        position: "relative",
        transform: `translateY(${phoneYOffset}px)`,
        boxShadow: "0 25px 50px -12px rgba(0,0,0,0.5)",
        display: "flex",
        transition: "none"
      }}>
        
        {/* Login Screen Context */}
        <div style={{
          position: "absolute", 
          width: "100%", 
          height: "100%",
          padding: 60, 
          display: "flex", 
          flexDirection: "column",
          transform: `translateX(${-screenOffset * 100}%)`,
          transition: "none"
        }}>
          <h1 style={{ 
            fontSize: 64, 
            color: textColor, 
            margin: "40px 0 60px 0", 
            fontWeight: 700 
          }}>
            {loginTitle}
          </h1>
          
          {/* Mock Inputs */}
          <div style={{ width: "100%", height: 80, backgroundColor: "#f1f5f9", borderRadius: 16, marginBottom: 24 }} />
          <div style={{ width: "100%", height: 80, backgroundColor: "#f1f5f9", borderRadius: 16, marginBottom: 40 }} />
          <div style={{ width: "100%", height: 90, backgroundColor: accentColor, borderRadius: 16, marginBottom: 60 }} />

          {/* Interactive Link */}
          <div style={{
            textAlign: "center", 
            fontSize: 32, 
            color: accentColor, 
            fontWeight: 600,
            transform: `scale(${activeTapScale})`, 
            transformOrigin: "center",
            transition: "none"
          }}>
            {forgotPasswordText}
          </div>
        </div>

        {/* Reset Screen Context */}
        <div style={{
          position: "absolute", 
          width: "100%", 
          height: "100%", 
          left: "100%",
          padding: 60, 
          display: "flex", 
          flexDirection: "column",
          transform: `translateX(${-screenOffset * 100}%)`,
          transition: "none"
        }}>
          <h1 style={{ 
            fontSize: 64, 
            color: textColor, 
            margin: "40px 0 60px 0", 
            fontWeight: 700 
          }}>
            {resetTitle}
          </h1>
          
          {/* Mock Input */}
          <div style={{ width: "100%", height: 80, backgroundColor: "#f1f5f9", borderRadius: 16, marginBottom: 40 }} />
          <div style={{ width: "100%", height: 90, backgroundColor: accentColor, borderRadius: 16 }} />
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default PasswordLoop;